+  mv.xy += position.xy * aB.w * 2.0 * vF;
+  vPx = aB.w * vF * projectionMatrix[1][1] / max(-mv.z, 0.1); // on-screen radius (fraction of the half-height)
+  gl_Position = projectionMatrix * mv;
